"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[3361],{5096(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>c,default:()=>u,frontMatter:()=>r,metadata:()=>s,toc:()=>p});const s=JSON.parse('{"id":"part2-backend-platform-security/http-methods","title":"HTTP Methods (Beginner-Friendly) \u2014 FastAPI","description":"HTTP methods tell the server (and intermediaries like browsers, proxies, CDNs) what you intend to do with a URL: read, create, replace, patch, delete. That intent unlocks important behavior like caching, retries, idem...","source":"@site/docs/part2-backend-platform-security/02-http-methods.mdx","sourceDirName":"part2-backend-platform-security","slug":"/part2-backend-platform-security/02-http-methods","permalink":"/tutorials/part2-backend-platform-security/02-http-methods","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":2,"frontMatter":{"title":"HTTP Methods (Beginner-Friendly) \u2014 FastAPI","slug":"/part2-backend-platform-security/02-http-methods","description":"HTTP methods tell the server (and intermediaries like browsers, proxies, CDNs) what you intend to do with a URL: read, create, replace, patch, delete. That intent unlocks important behavior like caching, retries, idem...","sidebar_label":"2. HTTP methods","pagination_label":"2. HTTP methods","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"1. FastAPI and Uvicorn basics","permalink":"/tutorials/part2-backend-platform-security/01-fastapi-uvicorn-basics"},"next":{"title":"3. FastAPI request mapping","permalink":"/tutorials/part2-backend-platform-security/03-fastapi-request-mapping"}}');var a=n(4848),d=n(8453),i=n(8172);const o=JSON.parse('{"sourcePath":"part2-backend-platform-security/02-http-methods.html","route":"/part2-backend-platform-security/02-http-methods","kind":"chapter","partId":"part2","partLabel":"Part II - Backend, Platform & Security","accent":"teal","heading":"HTTP methods (the \u201cverbs\u201d of the web) \u2014 beginner friendly","title":"HTTP Methods (Beginner-Friendly) \u2014 FastAPI","description":"HTTP methods tell the server (and intermediaries like browsers, proxies, CDNs) what you intend to do with a URL: read, create, replace, patch, delete. That intent unlocks important behavior like caching, retries, idem...","readingMinutes":6,"bodyClass":"","normalizeMath":false,"toc":[{"id":"core","label":"Core ideas you should know"},{"id":"contract-flow","label":"How this connects to Pydantic: method, URL, and body are separate jobs"},{"id":"methods-table","label":"Quick table (print-this-in-your-brain)"},{"id":"widely-used","label":"Widely used methods (you\u2019ll use these 99% of the time)"},{"id":"less-used","label":"Common but less used (still important)"},{"id":"rare","label":"Rare / niche methods (you\u2019ll see them sometimes)"},{"id":"rest","label":"Practical mapping to REST-style endpoints"},{"id":"put-vs-post","label":"The \u201cPUT vs POST feels same\u201d confusion (quick intuition)"},{"id":"request-shape","label":"What an HTTP request looks like"},{"id":"fastapi","label":"How FastAPI \u201cdecodes\u201d the message"}],"html":"<div class=\\"container\\">\\n        <div class=\\"header\\">\\n            <div>\\n                \\n                <p class=\\"lead\\">\\n                    HTTP methods tell the server (and intermediaries like browsers, proxies, CDNs) what you intend to do with a URL:\\n                    read, create, replace, patch, delete. That intent unlocks important behavior like caching, retries, idempotency,\\n                    and clearer security controls.\\n                </p>\\n\\n                <ul class=\\"toc\\">\\n                    <li><a href=\\"#core\\">Core ideas</a></li>\\n                    <li><a href=\\"#contract-flow\\">Method to Python contract</a></li>\\n                    <li><a href=\\"#methods-table\\">Quick table</a></li>\\n                    <li><a href=\\"#widely-used\\">Widely used (\u2b50)</a></li>\\n                    <li><a href=\\"#less-used\\">Less used but important</a></li>\\n                    <li><a href=\\"#rare\\">Rare / niche</a></li>\\n                    <li><a href=\\"#rest\\">REST-style mapping</a></li>\\n                    <li><a href=\\"#put-vs-post\\">PUT vs POST confusion</a></li>\\n                    <li><a href=\\"#request-shape\\">HTTP request shape</a></li>\\n                    <li><a href=\\"#fastapi\\">How FastAPI decodes</a></li>\\n                </ul>\\n            </div>\\n\\n            <aside class=\\"quickbox\\" aria-label=\\"Quick takeaway\\">\\n                <h3 id=\\"quick-takeaway\\">Quick takeaway</h3>\\n                <ul>\\n                    <li><span class=\\"badge get\\">GET</span> read (safe)</li>\\n                    <li><span class=\\"badge post\\">POST</span> create or run an action</li>\\n                    <li><span class=\\"badge put\\">PUT</span> replace full resource</li>\\n                    <li><span class=\\"badge patch\\">PATCH</span> partial update</li>\\n                    <li><span class=\\"badge delete\\">DELETE</span> remove</li>\\n                </ul>\\n                <p class=\\"cap\\" style=\\"margin: 10px 0 0; color: var(--muted);\\">\\n                    You\u2019ll use the \u2b50 methods 99% of the time.\\n                </p>\\n            </aside>\\n        </div>\\n\\n\\n        <h2 id=\\"core\\">Core ideas you should know</h2>\\n        <p class=\\"subtitle\\">These concepts explain why method choice matters (caching, retries, correctness).</p>\\n\\n        <div class=\\"grid\\">\\n            <div class=\\"mini col-6\\">\\n                <h3 id=\\"safe-vs-unsafe\\">Safe vs unsafe</h3>\\n                <p><strong>Safe</strong> means: \u201cshould not change server state\u201d (read-only).</p>\\n                <div class=\\"tag\\">\\n                    <span class=\\"chip safe\\">Safe: GET, HEAD, OPTIONS</span>\\n                    <span class=\\"chip unsafe\\">Unsafe: POST, PUT, PATCH, DELETE</span>\\n                </div>\\n            </div>\\n            <div class=\\"mini col-6\\">\\n                <h3 id=\\"idempotent-vs-non-idempotent\\">Idempotent vs non-idempotent</h3>\\n                <p><strong>Idempotent</strong> means: repeating the same request leads to the same final state as doing it once.</p>\\n                <div class=\\"tag\\">\\n                    <span class=\\"chip idem\\">Idempotent: GET, PUT, DELETE, HEAD, OPTIONS</span>\\n                    <span class=\\"chip nidem\\">Often non-idempotent: POST (and sometimes PATCH)</span>\\n                </div>\\n            </div>\\n            <div class=\\"mini col-12\\">\\n                <h3 id=\\"cacheable-common-in-practice\\">Cacheable (common in practice)</h3>\\n                <p>\\n                    <span class=\\"chip cache\\">GET is commonly cacheable</span>\\n                    <span class=\\"chip body\\">Others are usually not cached unless explicitly configured</span>\\n                </p>\\n            </div>\\n        </div>\\n\\n        <div class=\\"concept-box\\">\\n            <strong>Beginner rule:</strong> Pick the method that matches intent first.\\n            Then think about safety, idempotency, caching, and security.\\n            <span class=\\"pill\\">Method + URL = contract</span>\\n        </div>\\n\\n        <h2 id=\\"contract-flow\\">How this connects to Pydantic: method, URL, and body are separate jobs</h2>\\n        <p>\\n            A clean backend design separates three questions. First, the HTTP method says the intent:\\n            are we reading, creating, replacing, patching, or deleting? Second, the URL says which resource\\n            or collection the intent applies to. Third, if the request has a JSON body, a Pydantic model says\\n            the exact shape of that body.\\n        </p>\\n\\n        <div class=\\"concept-box\\">\\n            <strong>Flow to remember:</strong>\\n            <code>METHOD + URL</code> chooses the endpoint.\\n            <code>path/query/header</code> values become function parameters.\\n            <code>JSON body</code> becomes a Pydantic model instance when you declare one.\\n        </div>\\n\\n        <table aria-label=\\"HTTP method and Pydantic contract relationship\\">\\n            <thead>\\n                <tr>\\n                    <th>Request part</th>\\n                    <th>Example</th>\\n                    <th>Who handles it in FastAPI?</th>\\n                </tr>\\n            </thead>\\n            <tbody>\\n                <tr>\\n                    <td>Method + path</td>\\n                    <td><code>POST /orders</code></td>\\n                    <td>The route decorator: <code>@app.post(\\"/orders\\")</code></td>\\n                </tr>\\n                <tr>\\n                    <td>Path parameter</td>\\n                    <td><code>/users/42</code></td>\\n                    <td>A typed argument: <code>user_id: int</code></td>\\n                </tr>\\n                <tr>\\n                    <td>Query parameter</td>\\n                    <td><code>?limit=20</code></td>\\n                    <td>A typed argument with a default: <code>limit: int = 20</code></td>\\n                </tr>\\n                <tr>\\n                    <td>Header</td>\\n                    <td><code>Authorization: Bearer ...</code></td>\\n                    <td><code>Header(...)</code> or a security dependency</td>\\n                </tr>\\n                <tr>\\n                    <td>JSON body</td>\\n                    <td><code>{\\"items\\": [...]}</code></td>\\n                    <td>A Pydantic model such as <code>CreateOrderRequest</code></td>\\n                </tr>\\n            </tbody>\\n        </table>\\n\\n        <p>\\n            This means Pydantic is not a replacement for HTTP methods. It is the next layer down.\\n            The method tells the server what the client is trying to do; Pydantic validates the structured\\n            data the client sends while doing it.\\n        </p>\\n\\n        <h2 id=\\"methods-table\\">Quick table (print-this-in-your-brain)</h2>\\n        <p class=\\"subtitle\\">\u2b50 = widely used. Most APIs are mostly these 5.</p>\\n\\n        <table aria-label=\\"HTTP methods quick reference\\">\\n            <thead>\\n                <tr>\\n                    <th>Method</th>\\n                    <th>Intent</th>\\n                    <th>Safe?</th>\\n                    <th>Idempotent?</th>\\n                    <th>Commonly cacheable?</th>\\n                    <th>Body typical?</th>\\n                </tr>\\n            </thead>\\n            <tbody>\\n                <tr>\\n                    <td><span class=\\"badge star\\">\u2b50</span> <span class=\\"badge get\\">GET</span></td>\\n                    <td>Read data</td>\\n                    <td>Yes</td>\\n                    <td>Yes</td>\\n                    <td>Often</td>\\n                    <td>Usually no</td>\\n                </tr>\\n                <tr>\\n                    <td><span class=\\"badge star\\">\u2b50</span> <span class=\\"badge post\\">POST</span></td>\\n                    <td>Create / run action</td>\\n                    <td>No</td>\\n                    <td>No (by default)</td>\\n                    <td>Usually no</td>\\n                    <td>Often yes</td>\\n                </tr>\\n                <tr>\\n                    <td><span class=\\"badge star\\">\u2b50</span> <span class=\\"badge put\\">PUT</span></td>\\n                    <td>Replace full resource (or create at known URL)</td>\\n                    <td>No</td>\\n                    <td>Yes</td>\\n                    <td>Usually no</td>\\n                    <td>Often yes</td>\\n                </tr>\\n                <tr>\\n                    <td><span class=\\"badge star\\">\u2b50</span> <span class=\\"badge patch\\">PATCH</span></td>\\n                    <td>Partial update</td>\\n                    <td>No</td>\\n                    <td>Depends</td>\\n                    <td>Usually no</td>\\n                    <td>Often yes</td>\\n                </tr>\\n                <tr>\\n                    <td><span class=\\"badge star\\">\u2b50</span> <span class=\\"badge delete\\">DELETE</span></td>\\n                    <td>Remove resource</td>\\n                    <td>No</td>\\n                    <td>Yes (in intent)</td>\\n                    <td>Usually no</td>\\n                    <td>Usually no</td>\\n                </tr>\\n                <tr>\\n                    <td><span class=\\"badge\\">HEAD</span></td>\\n                    <td>Like GET, but headers only</td>\\n                    <td>Yes</td>\\n                    <td>Yes</td>\\n                    <td>Often</td>\\n                    <td>No</td>\\n                </tr>\\n                <tr>\\n                    <td><span class=\\"badge\\">OPTIONS</span></td>\\n                    <td>Discover what\u2019s allowed</td>\\n                    <td>Yes</td>\\n                    <td>Yes</td>\\n                    <td>Usually no</td>\\n                    <td>No</td>\\n                </tr>\\n            </tbody>\\n        </table>\\n\\n        <h2 id=\\"widely-used\\">Widely used methods (you\u2019ll use these 99% of the time)</h2>\\n\\n        <div class=\\"svgwrap\\" aria-label=\\"Inline diagram: method intent\\">\\n            <svg viewBox=\\"0 0 900 170\\" width=\\"100%\\" role=\\"img\\" aria-label=\\"Method intent diagram\\">\\n                <defs>\\n                    <linearGradient id=\\"g1\\" x1=\\"0\\" y1=\\"0\\" x2=\\"1\\" y2=\\"0\\">\\n                        <stop offset=\\"0\\" stop-color=\\"rgba(97,175,254,.35)\\"></stop>\\n                        <stop offset=\\"1\\" stop-color=\\"rgba(94,234,212,.18)\\"></stop>\\n                    </linearGradient>\\n                </defs>\\n                <rect x=\\"12\\" y=\\"14\\" width=\\"876\\" height=\\"142\\" rx=\\"16\\" fill=\\"url(#g1)\\" stroke=\\"rgba(255,255,255,.16)\\"></rect>\\n                <text x=\\"32\\" y=\\"55\\" fill=\\"rgba(230,234,242,.92)\\" font-size=\\"22\\" font-family=\\"ui-sans-serif, system-ui\\">Think of a URL like a noun (resource). Methods are verbs.</text>\\n                <text x=\\"32\\" y=\\"88\\" fill=\\"rgba(230,234,242,.88)\\" font-size=\\"18\\" font-family=\\"ui-sans-serif, system-ui\\">GET = read</text>\\n                <text x=\\"178\\" y=\\"88\\" fill=\\"rgba(230,234,242,.88)\\" font-size=\\"18\\" font-family=\\"ui-sans-serif, system-ui\\">POST = create/action</text>\\n                <text x=\\"392\\" y=\\"88\\" fill=\\"rgba(230,234,242,.88)\\" font-size=\\"18\\" font-family=\\"ui-sans-serif, system-ui\\">PUT = replace</text>\\n                <text x=\\"535\\" y=\\"88\\" fill=\\"rgba(230,234,242,.88)\\" font-size=\\"18\\" font-family=\\"ui-sans-serif, system-ui\\">PATCH = partial</text>\\n                <text x=\\"700\\" y=\\"88\\" fill=\\"rgba(230,234,242,.88)\\" font-size=\\"18\\" font-family=\\"ui-sans-serif, system-ui\\">DELETE = remove</text>\\n                <path fill=\\"none\\" d=\\"M32 110 H868\\" stroke=\\"rgba(255,255,255,.22)\\" stroke-width=\\"2\\"></path>\\n                <circle cx=\\"120\\" cy=\\"110\\" r=\\"7\\" fill=\\"#61affe\\"></circle>\\n                <circle cx=\\"292\\" cy=\\"110\\" r=\\"7\\" fill=\\"#49cc90\\"></circle>\\n                <circle cx=\\"468\\" cy=\\"110\\" r=\\"7\\" fill=\\"#fca130\\"></circle>\\n                <circle cx=\\"622\\" cy=\\"110\\" r=\\"7\\" fill=\\"#50e3c2\\"></circle>\\n                <circle cx=\\"800\\" cy=\\"110\\" r=\\"7\\" fill=\\"#f93e3e\\"></circle>\\n            </svg>\\n            <div class=\\"cap\\">Inline SVG \u201cimage\u201d: self-contained, no external assets.</div>\\n        </div>\\n\\n        \x3c!-- \u2b50 GET --\x3e\\n        <div class=\\"card\\">\\n            <h3 id=\\"get-read\\"><span class=\\"badge star\\">\u2b50</span> <span class=\\"badge get\\">GET</span> \u2014 read</h3>\\n            <p><strong>Use when</strong>: fetching data (read-only).</p>\\n            <p><strong>Example</strong>: <code>GET /users/42</code> \u2192 return user 42</p>\\n            <div class=\\"tag\\">\\n                <span class=\\"chip safe\\">Safe</span>\\n                <span class=\\"chip idem\\">Idempotent</span>\\n                <span class=\\"chip cache\\">Commonly cacheable</span>\\n            </div>\\n\\n            <h4>Full request message</h4>\\n<pre>GET /users/42?include=orders HTTP/1.1\\nHost: api.example.com\\nAuthorization: Bearer &lt;token&gt;\\nAccept: application/json</pre>\\n\\n            <h4>FastAPI</h4>\\n<pre>from fastapi import FastAPI\\n\\napp = FastAPI()\\n\\n@app.get(\\"/users/{user_id}\\")\\ndef get_user(user_id: int, include: str | None = None):\\n    return {\\"user_id\\": user_id, \\"include\\": include}</pre>\\n            <div class=\\"concept-box\\">\\n                <strong>Beginner tip:</strong> If you can bookmark it, refresh it, or share the URL and it still makes sense,\\n                it\u2019s probably a <code>GET</code>.\\n            </div>\\n        </div>\\n\\n        \x3c!-- \u2b50 POST --\x3e\\n        <div class=\\"card\\">\\n            <h3 id=\\"post-create-or-do-an-action\\"><span class=\\"badge star\\">\u2b50</span> <span class=\\"badge post\\">POST</span> \u2014 create or \u201cdo an action\u201d</h3>\\n            <p><strong>Use when</strong>:</p>\\n            <ul>\\n                <li>Creating a new resource under a collection (<code>POST /orders</code>)</li>\\n                <li>Triggering an operation that doesn\u2019t map cleanly to CRUD (<code>POST /reports/run</code>)</li>\\n            </ul>\\n            <p><strong>Example</strong>: <code>POST /orders</code> with body <code>{\\"items\\": [...]}</code> \u2192 creates a new order</p>\\n            <div class=\\"tag\\">\\n                <span class=\\"chip unsafe\\">Unsafe</span>\\n                <span class=\\"chip nidem\\">Not idempotent by default</span>\\n                <span class=\\"chip body\\">Body usually contains the \u201ccreate/action\u201d input</span>\\n            </div>\\n\\n            <h4>Full request message</h4>\\n<pre>POST /orders HTTP/1.1\\nHost: api.example.com\\nAuthorization: Bearer &lt;token&gt;\\nContent-Type: application/json\\nAccept: application/json\\n\\n{ \\"items\\": [{\\"sku\\": \\"ABC\\", \\"qty\\": 2}] }</pre>\\n\\n            <h4>FastAPI</h4>\\n<pre>from pydantic import BaseModel\\n\\nclass OrderItem(BaseModel):\\n    sku: str\\n    qty: int\\n\\nclass CreateOrderRequest(BaseModel):\\n    items: list[OrderItem]\\n\\n@app.post(\\"/orders\\")\\ndef create_order(payload: CreateOrderRequest):\\n    return {\\"created\\": True, \\"order_id\\": 123, \\"items\\": payload.items}</pre>\\n\\n            <p>\\n                The method <code>POST</code> says this is a create/action request.\\n                The Pydantic model <code>CreateOrderRequest</code> says what the JSON body must contain.\\n                Those are two different parts of the same API contract.\\n            </p>\\n        </div>\\n\\n        \x3c!-- \u2b50 PUT --\x3e\\n        <div class=\\"card\\">\\n            <h3 id=\\"put-replace-or-create-at-a-known-url\\"><span class=\\"badge star\\">\u2b50</span> <span class=\\"badge put\\">PUT</span> \u2014 replace (or create at a known URL)</h3>\\n            <p><strong>Use when</strong>: you want the resource at a URL to become exactly what you send.</p>\\n            <p><strong>Example</strong>: <code>PUT /users/42</code> with a full user object \u2192 replaces user 42</p>\\n            <div class=\\"tag\\">\\n                <span class=\\"chip unsafe\\">Unsafe</span>\\n                <span class=\\"chip idem\\">Idempotent</span>\\n                <span class=\\"chip body\\">Body usually contains the full resource state</span>\\n            </div>\\n\\n            <h4>Full request message</h4>\\n<pre>PUT /users/42 HTTP/1.1\\nHost: api.example.com\\nAuthorization: Bearer &lt;token&gt;\\nContent-Type: application/json\\nAccept: application/json\\n\\n{ \\"id\\": 42, \\"name\\": \\"Asha\\", \\"email\\": \\"asha@example.com\\" }</pre>\\n\\n            <div class=\\"warn\\">\\n                <strong>Common beginner bug:</strong> Using <code>PUT</code> with a partial body.\\n                <br>By intent, <code>PUT</code> is \u201creplace the full resource\u201d, so missing fields might get wiped unless you implement merge behavior.\\n            </div>\\n        </div>\\n\\n        \x3c!-- \u2b50 PATCH --\x3e\\n        <div class=\\"card\\">\\n            <h3 id=\\"patch-partial-update\\"><span class=\\"badge star\\">\u2b50</span> <span class=\\"badge patch\\">PATCH</span> \u2014 partial update</h3>\\n            <p><strong>Use when</strong>: updating only some fields.</p>\\n            <p><strong>Example</strong>: <code>PATCH /users/42</code> with <code>{\\"email\\": \\"new@x.com\\"}</code></p>\\n            <div class=\\"tag\\">\\n                <span class=\\"chip unsafe\\">Unsafe</span>\\n                <span class=\\"chip nidem\\">Idempotency depends on design</span>\\n                <span class=\\"chip body\\">Body contains only changed fields (usually)</span>\\n            </div>\\n\\n            <h4>Example PATCH request message</h4>\\n<pre>PATCH /users/42 HTTP/1.1\\nHost: api.example.com\\nAuthorization: Bearer &lt;token&gt;\\nContent-Type: application/json\\nAccept: application/json\\n\\n{ \\"email\\": \\"new@x.com\\" }</pre>\\n\\n            <div class=\\"concept-box\\">\\n                <strong>Idempotency note:</strong> A patch like \u201cset email to X\u201d is usually idempotent.\\n                A patch like \u201cincrement login_count by 1\u201d is not.\\n            </div>\\n        </div>\\n\\n        \x3c!-- \u2b50 DELETE --\x3e\\n        <div class=\\"card\\">\\n            <h3 id=\\"delete-remove\\"><span class=\\"badge star\\">\u2b50</span> <span class=\\"badge delete\\">DELETE</span> \u2014 remove</h3>\\n            <p><strong>Use when</strong>: deleting a resource.</p>\\n            <p><strong>Example</strong>: <code>DELETE /users/42</code></p>\\n            <div class=\\"tag\\">\\n                <span class=\\"chip unsafe\\">Unsafe</span>\\n                <span class=\\"chip idem\\">Idempotent in intent</span>\\n            </div>\\n            <div class=\\"concept-box\\">\\n                <strong>Beginner intuition:</strong> Deleting twice should still end \u201cdeleted\u201d.\\n                The second delete often returns <code>404</code> or <code>204</code> depending on API design.\\n            </div>\\n        </div>\\n\\n        <h2 id=\\"less-used\\">Common but less used (still important)</h2>\\n\\n        <div class=\\"card\\">\\n            <h3 id=\\"head-like-get-but-only-headers\\"><span class=\\"badge\\">HEAD</span> \u2014 like GET, but only headers</h3>\\n            <p><strong>Use when</strong>: you want metadata without downloading the body.</p>\\n            <p><strong>Example</strong>: check if a file changed using <code>ETag</code>/<code>Last-Modified</code>.</p>\\n        </div>\\n\\n        <div class=\\"card\\">\\n            <h3 id=\\"options-what-s-allowed-here\\"><span class=\\"badge\\">OPTIONS</span> \u2014 \u201cwhat\u2019s allowed here?\u201d</h3>\\n            <p><strong>Use when</strong>: discovering supported methods/headers.</p>\\n            <p><strong>Most common real-world use</strong>: CORS preflight (browser checks if it can call your API cross-origin).</p>\\n            <div class=\\"concept-box\\">\\n                If you ever see a browser sending an <code>OPTIONS</code> request before your real request,\\n                that\u2019s usually CORS, not \u201cyour frontend being weird\u201d.\\n            </div>\\n        </div>\\n\\n        <h2 id=\\"rare\\">Rare / niche methods (you\u2019ll see them sometimes)</h2>\\n        <div class=\\"card\\">\\n            <h3 id=\\"trace-diagnostic-often-disabled\\"><span class=\\"badge\\">TRACE</span> \u2014 diagnostic (often disabled)</h3>\\n            <p>Often disabled for security reasons.</p>\\n        </div>\\n        <div class=\\"card\\">\\n            <h3 id=\\"connect-tunneling-proxies-https\\"><span class=\\"badge\\">CONNECT</span> \u2014 tunneling (proxies + HTTPS)</h3>\\n            <p>Used to establish a tunnel through an HTTP proxy (common in corporate networks).</p>\\n        </div>\\n\\n        <h2 id=\\"rest\\">Practical mapping to REST-style endpoints</h2>\\n        <p class=\\"subtitle\\">Collections vs single resources</p>\\n\\n        <table aria-label=\\"REST mapping examples\\">\\n            <thead>\\n                <tr>\\n                    <th>Type</th>\\n                    <th>Method</th>\\n                    <th>Example</th>\\n                    <th>Meaning</th>\\n                </tr>\\n            </thead>\\n            <tbody>\\n                <tr>\\n                    <td>Collection</td>\\n                    <td><span class=\\"badge get\\">GET</span></td>\\n                    <td><code>GET /items</code></td>\\n                    <td>List/search items</td>\\n                </tr>\\n                <tr>\\n                    <td>Collection</td>\\n                    <td><span class=\\"badge post\\">POST</span></td>\\n                    <td><code>POST /items</code></td>\\n                    <td>Create a new item (server assigns ID)</td>\\n                </tr>\\n                <tr>\\n                    <td>Single resource</td>\\n                    <td><span class=\\"badge get\\">GET</span></td>\\n                    <td><code>GET /items/{id}</code></td>\\n                    <td>Read one item</td>\\n                </tr>\\n                <tr>\\n                    <td>Single resource</td>\\n                    <td><span class=\\"badge put\\">PUT</span></td>\\n                    <td><code>PUT /items/{id}</code></td>\\n                    <td>Replace item (or create if not exists)</td>\\n                </tr>\\n                <tr>\\n                    <td>Single resource</td>\\n                    <td><span class=\\"badge patch\\">PATCH</span></td>\\n                    <td><code>PATCH /items/{id}</code></td>\\n                    <td>Partial update</td>\\n                </tr>\\n                <tr>\\n                    <td>Single resource</td>\\n                    <td><span class=\\"badge delete\\">DELETE</span></td>\\n                    <td><code>DELETE /items/{id}</code></td>\\n                    <td>Delete</td>\\n                </tr>\\n            </tbody>\\n        </table>\\n\\n        <h2 id=\\"put-vs-post\\">The \u201cPUT vs POST feels same\u201d confusion (quick intuition)</h2>\\n        <div class=\\"grid\\">\\n            <div class=\\"mini col-6\\">\\n                <h3 id=\\"post-you-decide-what-happens\\"><span class=\\"badge post\\">POST</span> = \u201cYou decide what happens\u201d</h3>\\n                <p>\\n                    Think: \u201cHere\u2019s something; you decide what happens (often create a new thing).\u201d\\n                    The server usually chooses the new ID.\\n                </p>\\n            </div>\\n            <div class=\\"mini col-6\\">\\n                <h3 id=\\"put-make-this-url-have-this-exact-content\\"><span class=\\"badge put\\">PUT</span> = \u201cMake this URL have this exact content\u201d</h3>\\n                <p>\\n                    Think: \u201cMake <code>/users/42</code> look exactly like this payload.\u201d\\n                    You\u2019re targeting a specific URL.\\n                </p>\\n            </div>\\n        </div>\\n\\n        <div class=\\"concept-box\\">\\n            <strong>If you repeat the same request:</strong>\\n            <ul>\\n                <li>Repeating <code>PUT</code> should converge to the same final state (idempotent).</li>\\n                <li>Repeating <code>POST</code> can create duplicates unless you add idempotency keys.</li>\\n            </ul>\\n        </div>\\n\\n        <h2 id=\\"request-shape\\">What an HTTP request looks like</h2>\\n        <p>A client talks to your FastAPI backend by sending an HTTP request message:</p>\\n\\n        <pre>METHOD /path?query=string HTTP/1.1\\nHeader-Name: value\\nAuthorization: Bearer &lt;token&gt;\\nContent-Type: application/json\\n\\n{ \\"optional\\": \\"body\\" }</pre>\\n\\n        <ul>\\n            <li><strong>METHOD</strong>: intent (<code>GET</code>/<code>POST</code>/<code>PUT</code>/<code>PATCH</code>/<code>DELETE</code>)</li>\\n            <li><strong>/path</strong>: which resource (e.g. <code>/documents/123</code>)</li>\\n            <li><strong>?query=\u2026</strong>: options/filters (e.g. <code>?limit=20</code>)</li>\\n            <li><strong>Headers</strong>: metadata (auth token, content type)</li>\\n            <li><strong>Body</strong>: payload (often JSON; usually only for POST/PUT/PATCH)</li>\\n        </ul>\\n\\n        <h2 id=\\"fastapi\\">How FastAPI \u201cdecodes\u201d the message</h2>\\n        <p>FastAPI turns parts of the HTTP message into Python values using type hints:</p>\\n        <ul>\\n            <li><strong>Path params</strong> \u2192 function args (e.g. <code>user_id: int</code>)</li>\\n            <li><strong>Query params</strong> \u2192 function args (e.g. <code>limit: int = 20</code>)</li>\\n            <li><strong>Headers</strong> \u2192 via <code>Header(...)</code> or security dependencies</li>\\n            <li><strong>JSON body</strong> \u2192 Pydantic models (request schemas)</li>\\n        </ul>\\n        <p style=\\"color: #c0392b; font-style: italic;\\">If types don\u2019t match, FastAPI returns a 422 validation error automatically.</p>\\n\\n        <p class=\\"footer-note\\">\\n            Next step: read <a href=\\"/tutorials/part2-backend-platform-security/03-fastapi-request-mapping\\">the FastAPI request mapping chapter</a>\\n            to see one HTTP message become Python function arguments, then\\n            <a href=\\"/tutorials/part2-backend-platform-security/04-pydantic-data-models\\">the Pydantic chapter</a> to understand how JSON bodies\\n            become validated Python objects.\\n        </p>\\n    </div>"}'),r={title:"HTTP Methods (Beginner-Friendly) \u2014 FastAPI",slug:"/part2-backend-platform-security/02-http-methods",description:"HTTP methods tell the server (and intermediaries like browsers, proxies, CDNs) what you intend to do with a URL: read, create, replace, patch, delete. That intent unlocks important behavior like caching, retries, idem...",sidebar_label:"2. HTTP methods",pagination_label:"2. HTTP methods",hide_title:!0,hide_table_of_contents:!0},c=void 0,l={},p=[];function h(e){return(0,a.jsx)(i.A,{content:o})}function u(e={}){const{wrapper:t}={...(0,d.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(h,{...e})}):h()}}}]);